// src/decodeKeyTuple.ts
import { decodeAbiParameters } from "viem";
function decodeKeyTuple(keySchema, keyTuple) {
  if (keySchema.staticFields.length !== keyTuple.length) {
    throw new Error(
      `key tuple length ${keyTuple.length} does not match key schema length ${keySchema.staticFields.length}`
    );
  }
  return keyTuple.map(
    (key, index) => decodeAbiParameters([{ type: keySchema.staticFields[index] }], key)[0]
  );
}

// src/decodeKey.ts
